// Quiz bank, N10-009.
// [objective, question, options, answer index (or array for "choose two"), why the answer is right, why each option is wrong ('' = a correct option), 1 if the Corrections page covers it]
export const QB=[
["1.1", "At which OSI layer do routers make forwarding decisions?", ["Layer 2, Data Link", "Layer 3, Network", "Layer 4, Transport", "Layer 7, Application"], 1, "Routers forward packets by destination IP address, a Layer 3 address. Switches work at Layer 2 with MAC addresses; Layer 4 is ports; Layer 7 is the application protocol.", ["Layer 2 devices (switches) forward frames by MAC address, not IP.", "", "Layer 4 handles ports and reliability; it doesn't choose paths.", "Layer 7 is application protocols such as HTTP and DNS."]],
["1.1", "What is the PDU called at the Transport layer when TCP is used?", ["Frame", "Packet", "Segment", "Bits"], 2, "TCP's PDU at Layer 4 is the segment (UDP's is a datagram). Down the stack: segment → packet (L3) → frame (L2) → bits (L1).", ["A frame is the Layer 2 PDU.", "A packet is the Layer 3 (IP) PDU.", "", "Bits are the Layer 1 representation."]],
["1.1", "Which OSI layer adds the FCS trailer used for error detection?", ["Physical", "Data Link", "Network", "Transport"], 1, "The Ethernet frame ends with a Frame Check Sequence (CRC-32), added at Layer 2.", ["Layer 1 only sends bits; it has no error-checking trailer.", "", "IP has a header checksum but no trailer.", "TCP has a checksum in its header, not an FCS trailer."]],
["1.1", "A packet crosses two routers on its way to a server. What changes at each hop?", ["The source and destination IP addresses", "The frame's source and destination MAC addresses, and the TTL decrements", "Nothing at all", "The TCP port numbers"], 1, "Each router strips the frame and builds a new one with new MAC addresses. The IP addresses stay the same end to end (unless NAT rewrites them). MAC addresses never cross a router.", ["The IP addresses stay the same end to end; only NAT would change them.", "", "Every hop rebuilds the frame and decrements the TTL.", "Ports are Layer 4 and stay the same (unless PAT rewrites them)."]],
["1.1", "Which TCP flag ends a connection abruptly instead of gracefully?", ["FIN", "RST", "PSH", "SYN"], 1, "FIN/ACK closes gracefully. RST resets immediately. SYN opens, PSH asks for immediate delivery.", ["FIN closes a connection gracefully, with each side acknowledging.", "", "PSH asks for data to be passed to the application immediately.", "SYN opens a connection."]],
["1.1", "Which sequence is the TCP three-way handshake?", ["SYN → ACK → FIN", "SYN → SYN/ACK → ACK", "ACK → SYN → SYN/ACK", "SYN → SYN → ACK"], 1, "The client sends SYN, the server answers with a combined SYN/ACK, and the client confirms with ACK. Only then does data flow.", ["FIN is for closing, and the order is wrong.", "", "A handshake can't start with an ACK; there's nothing to acknowledge yet.", "The server replies with a combined SYN/ACK, not a second SYN."]],
["1.1", "What is the default Ethernet MTU?", ["1000 bytes", "1500 bytes", "1518 bytes", "9000 bytes"], 1, "The MTU (payload) is 1500 bytes. 1518 is the full frame size without a VLAN tag; about 9000 is a jumbo frame.", ["1000 bytes isn't a standard Ethernet value.", "", "1518 bytes is the whole frame (header + payload + FCS), not the MTU.", "About 9000 bytes is a jumbo frame and must be configured on purpose."]],
["1.2", "An appliance receives a copy of traffic from a SPAN port, alerts on suspicious patterns, and cannot block anything. What is it?", ["IPS", "IDS", "NGFW", "Load balancer"], 1, "An IDS is out of band: it detects and alerts. An IPS sits inline and blocks. An NGFW and a load balancer are inline devices.", ["An IPS sits inline and can block; this device only receives a copy.", "", "An NGFW is inline and enforces policy.", "A load balancer distributes connections; it doesn't inspect for threats."]],
["1.2", "Which device presents one virtual IP and spreads connections across a pool of web servers using health checks?", ["Forward proxy", "Load balancer", "Content filter", "IDS"], 1, "Load balancers add scale and resilience. A forward proxy acts for clients, not servers.", ["A forward proxy acts for clients going out, not for a server pool.", "", "A content filter blocks categories of sites.", "An IDS watches traffic; it doesn't distribute it."]],
["1.2", "A server needs block-level storage over the existing Ethernet network using initiators and targets. Which technology fits?", ["NAS with SMB", "iSCSI SAN", "NFS share", "CDN"], 1, "iSCSI carries SCSI block commands over IP. NAS, SMB and NFS are file-level. A CDN caches web content at the edge.", ["NAS with SMB is file-level storage, not block-level.", "", "NFS is also a file-level protocol.", "A CDN caches web content at the edge; it isn't server storage."]],
["1.2", "Which device sits in front of web servers and terminates TLS on their behalf?", ["Forward proxy", "Reverse proxy", "Transparent proxy", "Hub"], 1, "A reverse proxy acts for servers (TLS offload, protection). A forward proxy acts for clients.", ["A forward proxy acts on behalf of clients, not servers.", "", "A transparent proxy intercepts client traffic without configuration; it doesn't front servers.", "A hub is a Layer 1 repeater with no TLS ability."]],
["1.2", "Which firewall type automatically allows return traffic for connections started from inside?", ["Stateless packet filter", "Stateful firewall", "Router ACL", "Hub"], 1, "A stateful firewall tracks connections. A stateless filter checks each packet alone, so return traffic needs its own rule.", ["A stateless filter checks each packet alone, so return traffic needs its own rule.", "", "A basic router ACL is stateless too.", "A hub doesn't filter traffic at all."]],
["1.3", "A cloud provider manages the hardware, OS and runtime; your team only deploys code. Which service model is this?", ["IaaS", "PaaS", "SaaS", "DaaS"], 1, "With IaaS you manage the OS. With SaaS you only use the finished app. DaaS is hosted desktops.", ["With IaaS you manage the OS and runtime yourself.", "", "With SaaS you only use a finished application; you don't deploy code.", "DaaS delivers virtual desktops."]],
["1.3", "Instances in a private cloud subnet must download updates but must not be reachable from the Internet. What should you add?", ["Internet gateway", "NAT gateway", "Public IP on each instance", "VPN concentrator"], 1, "A NAT gateway allows outbound-initiated connections only. An Internet gateway and public IPs make instances reachable.", ["An Internet gateway allows inbound connections too, which is exactly what must be avoided.", "", "A public IP makes each instance reachable from the Internet.", "A VPN concentrator terminates VPN tunnels; it doesn't give outbound Internet access."]],
["1.3", "Resources scale up and back down automatically as demand changes. What is this called?", ["Multitenancy", "Elasticity", "Scalability by hand", "High availability"], 1, "Scalability is the ability to grow. Elasticity means doing it automatically in both directions.", ["Multitenancy means customers share infrastructure; it says nothing about scaling.", "", "Scaling by hand is scalability, but not automatic.", "High availability is about surviving failures, not matching demand."]],
["1.3", "Which cloud control applies rules at the subnet level and is usually stateless?", ["Network security group", "Network security list / NACL", "Host firewall", "WAF"], 1, "Security groups are stateful and apply per instance or NIC. Security lists/NACLs apply per subnet and are usually stateless.", ["Security groups are stateful and apply per instance or NIC.", "", "A host firewall runs on one machine, not on the subnet.", "A WAF inspects web application traffic (Layer 7)."]],
["1.3", "Running a firewall as a virtual machine instead of a dedicated appliance is an example of:", ["NFV", "SDN", "VXLAN", "SASE"], 0, "Network functions virtualization replaces hardware appliances with software.", ["", "SDN separates the control plane from the data plane; it doesn't virtualize appliances.", "VXLAN is an overlay that carries Layer 2 frames across Layer 3.", "SASE is cloud-delivered security plus SD-WAN."]],
["1.4", "Which port does LDAPS use?", ["389", "636", "443", "3389"], 1, "LDAPS is LDAP wrapped in TLS, on TCP 636. Plain LDAP uses 389.", ["389 is plain LDAP.", "", "443 is HTTPS.", "3389 is RDP."]],
["1.4", "A manager receives unsolicited SNMP traps on which port?", ["UDP 161", "UDP 162", "TCP 22", "UDP 514"], 1, "Agents send unsolicited traps to the manager on UDP 162. The manager polls agents on UDP 161.", ["UDP 161 is where agents are polled, not where traps go.", "", "TCP 22 is SSH.", "UDP 514 is syslog."]],
["1.4", "DNS zone transfers between primary and secondary servers use:", ["UDP 53", "TCP 53", "UDP 67", "TCP 853"], 1, "Queries normally use UDP 53. Zone transfers and large responses use TCP 53. 853 is DNS over TLS.", ["UDP 53 carries normal queries; zone transfers need TCP's reliability.", "", "UDP 67 is the DHCP server.", "TCP 853 is DNS over TLS, not zone transfers."]],
["1.4", "Choose two. Which protocols normally use UDP?", ["TFTP", "SSH", "Syslog", "RDP"], [0, 2], "TFTP (69) and syslog (514) are lightweight and connectionless, so they use UDP.", ["", "SSH uses TCP 22.", "", "RDP uses TCP 3389 (UDP is optional, not the norm)."]],
["1.4", "Which IPsec protocol provides encryption?", ["AH", "ESP", "IKE", "GRE"], 1, "ESP encrypts and authenticates. AH gives integrity and authentication only. IKE negotiates keys. GRE has no encryption at all.", ["AH provides integrity and authentication but no encryption.", "", "IKE negotiates keys; it doesn't encrypt the data.", "GRE is a tunnel with no encryption at all."]],
["1.4", "Which traffic type does IPv6 NOT have?", ["Unicast", "Multicast", "Anycast", "Broadcast"], 3, "IPv6 has no broadcast. It uses multicast instead (for example NDP's solicited-node multicast replaces ARP's broadcast).", ["IPv6 has unicast.", "IPv6 has multicast (ff00::/8); it replaces broadcast.", "IPv6 has anycast.", ""]],
["1.4", "Which range holds dynamic (ephemeral) client source ports?", ["0–1023", "1024–49151", "49152–65535", "1–65535"], 2, "Clients pick a temporary source port from the dynamic range, 49152–65535. 0–1023 are well-known and 1024–49151 are registered.", ["0–1023 are well-known (server) ports.", "1024–49151 are registered ports.", "", "That's the whole port range, not the dynamic part."]],
["1.4", "Which is the secure replacement for SNMPv2c?", ["SNMPv1", "SNMPv3", "Syslog over TLS", "NetFlow"], 1, "SNMPv3 adds authentication, integrity and encryption. v1 and v2c send community strings in clear text.", ["SNMPv1 is older and less secure.", "", "Syslog carries logs; it doesn't replace SNMP management.", "NetFlow records traffic flows; it doesn't manage devices."]],
["1.5", "Which fiber connector is small form factor with a latch and is the usual connector on SFP modules?", ["ST", "SC", "LC", "F-type"], 2, "LC: small, latching. SC: square push-pull. ST: round bayonet. F-type is a coax connector.", ["ST is a round bayonet twist-lock connector.", "SC is a larger square push-pull connector.", "", "F-type is a coax connector."]],
["1.5", "Which cable category supports 10GBASE-T over the full 100 meters?", ["Cat 5e", "Cat 6", "Cat 6a", "Cat 3"], 2, "Cat 6a is rated for 10GBASE-T over the full 100 m. Cat 6 manages only about 55 m at 10 Gbps.", ["Cat 5e tops out at 1 Gbps.", "Cat 6 manages 10GBASE-T only to about 55 m.", "", "Cat 3 is old telephone/10 Mbps cable."]],
["1.5", "What is the maximum distance for 25G/40GBASE-T over Cat 8?", ["100 m", "55 m", "30 m", "10 m"], 2, "Cat 8 supports 25G/40GBASE-T only up to 30 m, which is meant for short data center runs between racks.", ["100 m is the limit for Cat 5e/6/6a, not Cat 8.", "55 m is Cat 6 at 10 Gbps.", "", "Cat 8 reaches further than 10 m."]],
["1.5", "Cable is being pulled through the space above a drop ceiling that is used for air return. What jacket is required?", ["PVC", "Riser", "Plenum", "Direct burial"], 2, "Plenum-rated cable is fire-resistant and low-smoke. Riser is for vertical runs between floors.", ["PVC gives off toxic smoke and isn't allowed in air-handling spaces.", "Riser is for vertical runs between floors.", "", "Direct burial cable is for underground runs."]],
["1.5", "Which cable connects a laptop's serial/USB adapter to a switch console port?", ["Straight-through", "Crossover", "Rollover (console)", "Twinax"], 2, "A rollover cable reverses all pins. Straight-through connects host↔switch; crossover connects like devices.", ["Straight-through connects unlike devices, such as a PC to a switch.", "Crossover connects like devices, such as switch to switch.", "", "Twinax is DAC for SFP+ ports."]],
["1.5", "A technician is about to connect an APC (green) fiber connector to a UPC (blue) port. What should they do?", ["Connect it; they are compatible", "Stop: never mate APC with UPC", "Clean the connector first and connect", "Use a crossover patch"], 1, "APC ends have an 8° angle and UPC ends are flat. Mating them causes high loss and can damage the end faces.", ["APC (angled) and UPC (flat) end faces don't mate properly.", "", "Cleaning doesn't fix the angle mismatch.", "A crossover patch doesn't change the end-face geometry."]],
["1.5", "Which optics are designed for 10 km over single-mode fiber at 1310 nm?", ["10GBASE-SR", "10GBASE-LR", "10GBASE-ER", "10GBASE-T"], 1, "S = short reach/multimode, L = long reach/single-mode (10 km), E = extended reach (40 km at 1550 nm).", ["SR is short reach over multimode (850 nm).", "", "ER is extended reach, 40 km at 1550 nm.", "10GBASE-T is copper."]],
["1.5", "A provider wants to carry dozens of wavelengths on one fiber pair for a long-haul link. Which technology fits?", ["CWDM", "DWDM", "BiDi", "MPO"], 1, "Dense WDM packs many channels for long-haul and metro links. Coarse WDM has fewer channels and is cheaper.", ["CWDM uses fewer, wider-spaced channels and is cheaper.", "", "BiDi uses two wavelengths on one strand, not dozens.", "MPO is a multi-fiber connector, not a wavelength technology."]],
["1.5", "What is the cheapest way to connect a server to the top-of-rack switch 3 m away at 10 Gbps?", ["Single-mode fiber with LR optics", "DAC (twinax) cable", "Cat 5e", "RG-6 coax"], 1, "A DAC (twinax) cable is short, cheap copper with SFP+ ends built on. It's ideal for a few metres inside a rack.", ["SMF with LR optics works but is far more expensive than needed for 3 m.", "", "Cat 5e can't carry 10 Gbps reliably.", "RG-6 is for cable TV and modems."]],
["1.5", "What speed does a QSFP28 module support?", ["10 Gbps", "25 Gbps", "40 Gbps", "100 Gbps"], 3, "QSFP28 carries four 25 Gbps lanes, giving 100 Gbps. SFP+ is 10G, SFP28 is 25G and QSFP+ is 40G.", ["10 Gbps is SFP+.", "25 Gbps is SFP28.", "40 Gbps is QSFP+.", ""]],
["1.6", "Which topology gives the most redundancy at the highest cabling cost?", ["Star", "Bus", "Full mesh", "Hub-and-spoke"], 2, "A full mesh connects every node to every other node, so it survives the most failures but needs n(n−1)/2 links.", ["In a star, the central device is a single point of failure.", "On a bus, one break takes down the whole segment.", "", "Hub-and-spoke depends on the hub."]],
["1.6", "How many links does a full mesh of 6 sites need?", ["6", "12", "15", "30"], 2, "Full-mesh links = n(n−1) ÷ 2 = 6 × 5 ÷ 2 = 15.", ["6 is the number of sites, not links.", "12 is n × 2.", "", "30 is n(n−1) without dividing by 2."]],
["1.6", "In a spine-and-leaf design, each leaf switch connects to:", ["One spine only", "Every spine switch", "Other leaf switches", "The edge router directly"], 1, "Every leaf connects to every spine and leaves never connect to each other, so every east-west path is the same length.", ["Every leaf connects to every spine, not just one.", "", "Leaves never connect to each other.", "Leaves connect to spines; the edge connects elsewhere."]],
["1.6", "A small site merges the core and distribution layers into one tier. What is this called?", ["Spine-and-leaf", "Collapsed core", "Hub-and-spoke", "Full mesh"], 1, "A collapsed core merges the core and distribution layers into one tier, which cuts cost for smaller sites.", ["Spine-and-leaf is a data center design, not a merged tier.", "", "Hub-and-spoke is a WAN topology.", "Full mesh connects every node to every other."]],
["1.6", "Server-to-server traffic inside a data center is described as:", ["North-south", "East-west", "Point-to-multipoint", "Broadcast"], 1, "North-south traffic goes in and out of the data center; east-west traffic stays between servers inside it.", ["North-south is traffic in and out of the data center.", "", "Point-to-multipoint is a link type, not a traffic direction.", "Broadcast is a delivery method."]],
["1.6", "Where does the ISP's responsibility for a circuit end?", ["The MDF", "The demarcation point (demarc)", "The patch panel", "The first router hop"], 1, "The demarcation point (demarc) is where the provider's responsibility ends and yours begins. A demarc extension can carry it to your equipment room.", ["The MDF is your main equipment room.", "", "The patch panel is your cabling.", "The ISP's responsibility ends before your router."]],
["1.7", "Which of these is a private (RFC 1918) address?", ["172.32.10.5", "192.169.1.20", "172.20.4.9", "11.0.0.1"], 2, "Private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 and 192.168.0.0/16.", ["172.32.x.x is just past the private 172.16.0.0/12 block.", "192.169.x.x is not 192.168.", "", "11.x.x.x is public; only 10.x.x.x is private."]],
["1.7", "A workstation shows 169.254.33.7. What happened?", ["It has a static IP", "It did not get a DHCP lease and self-assigned APIPA", "It is IPv6-only", "It is on a VPN"], 1, "169.254.0.0/16 is APIPA: Windows assigns it when no DHCP server answers. Check DHCP reachability first.", ["A static IP would be in the configured range, not 169.254.", "", "An IPv6-only host wouldn't show an IPv4 address at all.", "A VPN gives an address from the VPN pool."]],
["1.7", "How many usable hosts are in a /27?", ["30", "32", "62", "14"], 0, "A /27 leaves 5 host bits: 2^5 = 32 addresses, minus the network and broadcast addresses = 30 usable.", ["", "32 is the total, including the network and broadcast addresses.", "62 is a /26.", "14 is a /28."]],
["1.7", "What is the broadcast address of 192.168.10.77/27?", ["192.168.10.63", "192.168.10.95", "192.168.10.127", "192.168.10.255"], 1, "Block size 32: the subnet is .64, the broadcast is .95, and hosts are .65–.94.", ["192.168.10.63 is the broadcast of the .32 subnet.", "", "192.168.10.127 would be a /25.", "192.168.10.255 would be a /24."]],
["1.7", "What is the usable Class A first-octet range?", ["0–127", "1–126", "1–127", "0–126"], 1, "0 is reserved and 127 is loopback. Some quiz material lists 0–126, which is wrong.", ["0 is reserved and 127 is loopback.", "", "127 is loopback, not usable.", "0 is reserved."], 1],
["1.7", "Which prefix is used only for point-to-point links and gives exactly two usable addresses with no network or broadcast address?", ["/29", "/30", "/31", "/32"], 2, "/31 (RFC 3021) is for point-to-point links. A /30 has 4 addresses with 2 usable. A /32 is a single host route.", ["/29 has 6 usable addresses.", "/30 has 4 addresses but only 2 usable (network and broadcast are lost).", "", "/32 is a single host route."]],
["1.8", "What does SDN separate?", ["Access and core layers", "The control plane from the data (forwarding) plane", "IPv4 from IPv6", "Voice from data"], 1, "Decisions move to a central controller, which programs devices through southbound APIs.", ["The three-tier model, not SDN, defines access and core layers.", "", "Dual stack covers IPv4 and IPv6.", "Voice VLANs separate voice from data."]],
["1.8", "Which technology carries Layer 2 frames inside UDP so they can cross a Layer 3 data center fabric?", ["VXLAN", "GRE", "MPLS", "802.1Q"], 0, "VXLAN uses UDP 4789 and a 24-bit VNI, giving about 16 million segments compared with 4094 VLANs.", ["", "GRE tunnels packets but isn't the data center L2-over-UDP overlay.", "MPLS is label switching in provider networks.", "802.1Q tags VLANs on a trunk; it doesn't cross Layer 3."]],
["1.8", "Which architecture combines SD-WAN with cloud-delivered security such as SWG, CASB and ZTNA?", ["SASE", "NFV", "IaC", "VPC"], 0, "SASE combines SD-WAN with cloud-delivered security (SWG, CASB, ZTNA, firewall-as-a-service). SSE is just the security half.", ["", "NFV virtualizes appliances.", "IaC is configuration as code.", "A VPC is a private network in a cloud."]],
["1.8", "Zero trust architecture assumes that:", ["Internal traffic is trusted", "No user or device is trusted by default; every request is verified", "VPN users are always trusted", "The perimeter firewall is enough"], 1, "Zero trust means never trust, always verify: every request is authenticated and authorized, whatever network it comes from.", ["Zero trust is the opposite: location gives no trust.", "", "VPN users are verified too.", "Zero trust doesn't rely on the perimeter."]],
["1.8", "What is a key benefit of managing device configurations as Infrastructure as Code in source control?", ["It removes the need for backups", "It prevents configuration drift and makes changes repeatable", "It encrypts traffic", "It replaces routing protocols"], 1, "Templates and playbooks remove manual errors. Version control shows who changed what.", ["You still need backups.", "", "IaC manages configuration; it doesn't encrypt.", "It configures routing; it doesn't replace it."]],
["1.8", "Which IPv6 prefix is link-local?", ["2000::/3", "fc00::/7", "fe80::/10", "ff00::/8"], 2, "Global unicast is 2000::/3, unique local is fc00::/7 (fd00::/8 in practice), and multicast is ff00::/8.", ["2000::/3 is global unicast.", "fc00::/7 is unique local.", "", "ff00::/8 is multicast."]],
["1.8", "What EUI-64 interface ID is created from MAC 00:1A:2B:3C:4D:5E?", ["001A:2BFF:FE3C:4D5E", "021A:2BFF:FE3C:4D5E", "001A:2BFE:FF3C:4D5E", "021A:2B3C:4D5E:FFFE"], 1, "Split the MAC, insert FFFE in the middle, then flip the 7th bit of the first byte (00 → 02).", ["The 7th bit wasn't flipped (00 should become 02).", "", "FFFE goes in the middle as FF:FE, not FE:FF.", "FFFE goes in the middle, not at the end."]],
["1.8", "Which protocol replaces ARP in IPv6?", ["DHCPv6", "NDP (ICMPv6)", "SLAAC", "IGMP"], 1, "NDP uses Neighbor Solicitation and Neighbor Advertisement messages, plus Router Solicitation/Advertisement.", ["DHCPv6 assigns addresses and options.", "", "SLAAC is self-assigning an address from the RA.", "IGMP is IPv4 multicast group management."]],
["1.8", "Which transition technology tunnels IPv6 through IPv4 NAT using UDP?", ["ISATAP", "Teredo", "NAT64", "Dual stack"], 1, "ISATAP works inside a site. NAT64 translates rather than tunnels. Dual stack is not a tunnel.", ["ISATAP tunnels inside a site and doesn't cross NAT.", "", "NAT64 translates between IPv6 and IPv4; it doesn't tunnel.", "Dual stack runs both natively; there's no tunnel."]],
["2.1", "A router learns 10.1.1.0/24 from a static route (AD 1) and from OSPF (AD 110). Which goes in the routing table?", ["OSPF, because it is dynamic", "The static route, because its AD is lower", "Both, load-balanced", "Neither"], 1, "Both routes are for the same prefix, so administrative distance decides. Static (1) is more trusted than OSPF (110).", ["Being dynamic doesn't win; lower AD (more trusted) does.", "", "Different sources for the same prefix don't load-balance; AD picks one.", "One of them is always installed."]],
["2.1", "A router has 10.0.0.0/8, 10.1.0.0/16 and 10.1.1.0/24. Which route does it use for 10.1.1.50?", ["10.0.0.0/8", "10.1.0.0/16", "10.1.1.0/24", "The default route"], 2, "Routers always use the longest prefix match first: 10.1.1.0/24 is the most specific route containing 10.1.1.50. AD only matters between routes for the same prefix.", ["A /8 matches, but it's the least specific.", "A /16 matches, but the /24 is more specific.", "", "The default route is only used when nothing more specific matches."]],
["2.1", "Which routing protocol is path-vector and runs between autonomous systems on the Internet?", ["OSPF", "RIPv2", "EIGRP", "BGP"], 3, "OSPF is link state, RIP is distance vector, and EIGRP is advanced distance vector (hybrid).", ["OSPF is a link-state IGP.", "RIPv2 is a distance-vector IGP.", "EIGRP is an advanced distance-vector IGP.", ""]],
["2.1", "What is RIP's maximum hop count?", ["15", "16", "255", "100"], 0, "RIP's metric is hop count, with a maximum of 15. A count of 16 means unreachable, which limits RIP to small networks.", ["", "16 means unreachable in RIP.", "255 is the IP TTL maximum.", "100 has no meaning in RIP."]],
["2.1", "What is the default administrative distance of internal EIGRP?", ["1", "90", "110", "120"], 1, "Internal EIGRP has an AD of 90. For reference: connected 0, static 1, eBGP 20, EIGRP 90, OSPF 110, RIP 120, iBGP 200.", ["1 is static.", "", "110 is OSPF.", "120 is RIP."]],
["2.1", "Many inside hosts share one public IP, told apart by source port. What is this?", ["Static NAT", "PAT (NAT overload)", "Dynamic NAT", "NAT64"], 1, "PAT (NAT overload) maps many inside hosts onto one public IP and tells them apart by unique source port numbers.", ["Static NAT is 1:1, one private to one public.", "", "Dynamic NAT maps to a pool without port translation.", "NAT64 translates IPv6 to IPv4."]],
["2.1", "In NAT terminology, a host's private address before translation is the:", ["Inside global", "Inside local", "Outside local", "Outside global"], 1, "Inside local is the inside host's real (private) address before translation. Inside global is the public address that represents it.", ["Inside global is the public address representing the inside host.", "", "Outside local describes the remote host.", "Outside global is the remote host's real address."]],
["2.1", "Which protocol gives hosts a redundant default gateway through a shared virtual IP?", ["VRRP", "OSPF", "LLDP", "LACP"], 0, "VRRP lets two or more routers share a virtual IP and MAC as the hosts' gateway, so a standby takes over if the active router fails. HSRP is Cisco's version.", ["", "OSPF is a routing protocol.", "LLDP is neighbor discovery.", "LACP is link aggregation."]],
["2.1", "One physical router interface split into 802.1Q subinterfaces, one per VLAN, is called:", ["Router-on-a-stick", "Collapsed core", "Port channel", "Split horizon"], 0, "Router-on-a-stick splits one router interface into 802.1Q subinterfaces, one gateway per VLAN, for inter-VLAN routing without a Layer 3 switch.", ["", "Collapsed core merges network tiers.", "A port channel bundles links.", "Split horizon is a distance-vector loop-prevention rule."]],
["2.2", "Which standard tags Ethernet frames with a VLAN ID on a trunk?", ["802.1X", "802.1Q", "802.3af", "802.1D"], 1, "802.1Q adds a 4-byte tag with a 12-bit VLAN ID. 802.1X is port authentication, 802.3af is PoE, 802.1D is STP.", ["802.1X is port-based authentication.", "", "802.3af is PoE.", "802.1D is the original STP."]],
["2.2", "On an 802.1Q trunk, frames from which VLAN are sent untagged?", ["Always VLAN 1", "The native VLAN", "The voice VLAN", "None"], 1, "Frames in the native VLAN cross the trunk untagged. It's VLAN 1 by default; change it to an unused VLAN and make it match on both ends.", ["VLAN 1 is only the default native VLAN; it can be changed.", "", "The voice VLAN is tagged.", "The native VLAN is untagged."]],
["2.2", "How is the STP root bridge elected?", ["Highest MAC address", "Lowest bridge ID (priority, then MAC)", "Most ports", "First switch powered on"], 1, "The switch with the lowest bridge ID wins: lowest priority first (default 32768), then lowest MAC as the tie-breaker. Lower the priority on the switch you want as root.", ["The lowest bridge ID wins, not the highest MAC.", "", "The number of ports doesn't matter.", "Boot order doesn't matter."]],
["2.2", "In which STP state does a port learn MAC addresses but not forward frames yet?", ["Blocking", "Listening", "Learning", "Forwarding"], 2, "Blocking receives BPDUs only. Listening decides port roles. Learning fills the MAC table. Forwarding works fully.", ["Blocking only receives BPDUs.", "Listening decides port roles but doesn't learn MACs.", "", "Forwarding learns and forwards."]],
["2.2", "Which feature shuts down an access port that receives a BPDU?", ["Root Guard", "BPDU Guard", "Storm control", "PortFast"], 1, "BPDU Guard err-disables an access port as soon as it receives a BPDU, which stops someone plugging a rogue switch into a user port.", ["Root Guard stops a port from becoming the path to a new root; it doesn't shut it down on any BPDU.", "", "Storm control limits broadcast and multicast floods.", "PortFast skips listening and learning; it doesn't block BPDUs."]],
["2.2", "Which protocol bundles several physical links into one logical link?", ["LACP (802.3ad)", "STP", "VRRP", "CDP"], 0, "LACP (802.3ad) negotiates several physical links into one logical link for more bandwidth and redundancy. It's also called a port channel, EtherChannel or NIC teaming.", ["", "STP prevents loops.", "VRRP is gateway redundancy.", "CDP is Cisco neighbor discovery."]],
["2.2", "A PTZ camera needs about 25 W at the device. What is the minimum PoE standard?", ["802.3af", "802.3at (PoE+)", "802.3bt is required", "Passive PoE"], 1, "802.3af supplies 15.4 W at the switch (about 12.95 W at the device). 802.3at supplies 30 W (about 25.5 W). Some handouts wrongly call 802.3af \"PoE+\".", ["802.3af gives only about 12.95 W at the device.", "", "802.3bt works but isn't the minimum.", "Passive PoE isn't a negotiated standard."], 1],
["2.2", "Copying all traffic from one switch port to a monitoring port is called:", ["Port mirroring (SPAN)", "Port security", "Trunking", "Link aggregation"], 0, "Port mirroring (SPAN) copies traffic from one port or VLAN to a monitoring port, to feed an analyzer or IDS.", ["", "Port security limits MACs on a port.", "Trunking carries VLANs.", "Link aggregation bundles links."]],
["2.2", "An IP phone and a PC share one switch port. What keeps their traffic separate?", ["Native VLAN", "Voice VLAN", "Private VLAN", "VLAN 1"], 1, "The phone tags voice traffic in the voice VLAN. The PC's traffic stays in the data VLAN.", ["The native VLAN is untagged and isn't meant for voice.", "", "Private VLANs isolate hosts from each other.", "VLAN 1 is the default VLAN."]],
["2.3", "Which 2.4 GHz channels do not overlap (North America)?", ["1, 5, 9", "1, 6, 11", "2, 7, 12", "3, 8, 13"], 1, "In the 2.4 GHz band, only 20 MHz channels 1, 6 and 11 don't overlap, so neighboring APs should use those.", ["1, 5, 9 overlap with each other.", "", "2, 7, 12 isn't the standard set.", "3, 8, 13 isn't the standard set (13 isn't used in North America)."]],
["2.3", "What does Wi-Fi 6E add compared with Wi-Fi 6?", ["900 MHz", "The 6 GHz band", "60 GHz", "A new security protocol only"], 1, "Wi-Fi 6E is Wi-Fi 6 extended into the 6 GHz band, which offers many more clean channels. WPA3 is required there.", ["900 MHz isn't a Wi-Fi 6E band.", "", "60 GHz is 802.11ad/ay.", "WPA3 is required on 6 GHz, but the addition is the band."]],
["2.3", "Which security protocol replaces the PSK handshake with SAE?", ["WEP", "WPA", "WPA2", "WPA3"], 3, "WPA3 replaces the pre-shared-key handshake with SAE, which resists offline dictionary attacks against the handshake.", ["WEP is broken.", "WPA used TKIP.", "WPA2 uses AES-CCMP with a PSK handshake.", ""]],
["2.3", "Which standard introduced OFDMA to Wi-Fi?", ["802.11n", "802.11ac", "802.11ax", "802.11g"], 2, "802.11ax (Wi-Fi 6) introduced OFDMA, which splits a channel among several clients at once, along with uplink MU-MIMO.", ["802.11n introduced MIMO.", "802.11ac introduced downlink MU-MIMO.", "", "802.11g is old 2.4 GHz OFDM."]],
["2.3", "Downlink MU-MIMO first appeared in:", ["802.11n", "802.11ac Wave 2", "802.11ax", "802.11g"], 1, "The book says 802.11ax introduced it. That is wrong: 802.11ac Wave 2 added downlink MU-MIMO, and 802.11ax added uplink MU-MIMO.", ["802.11n has single-user MIMO only.", "", "802.11ax added uplink MU-MIMO. Your book says it introduced MU-MIMO; that's wrong.", "802.11g has no MIMO."], 1],
["2.3", "Which antenna fits a point-to-point link between two buildings?", ["Omnidirectional dipole", "Directional (Yagi or parabolic)", "Patch antenna inside a laptop", "Any antenna works"], 1, "Directional antennas such as Yagi or parabolic focus energy in one direction, which gives the range a building-to-building link needs.", ["An omnidirectional antenna spreads signal 360°, wasting it for long links.", "", "A patch antenna inside a laptop is low gain.", "Long links need high-gain directional antennas."]],
["2.3", "Guest Wi-Fi shows a terms-of-use page before allowing Internet access. What is this?", ["Captive portal", "WPA3-Enterprise", "MAC filtering", "Client isolation"], 0, "A captive portal shows a terms or login page before granting access. Pair it with a separate guest VLAN and client isolation.", ["", "WPA3-Enterprise authenticates with 802.1X, not a terms page.", "MAC filtering silently allows or blocks devices.", "Client isolation stops guests talking to each other."]],
["2.3", "Several APs share one SSID so users can roam between them. This is an:", ["IBSS", "ESS (extended service set)", "Ad hoc network", "BSSID"], 1, "An ESS is several APs sharing one SSID, so clients can roam between them. Each AP radio has its own BSSID.", ["An IBSS is ad hoc, with no AP.", "", "Ad hoc has no APs.", "A BSSID is one AP radio's MAC address."]],
["2.3", "Which design uses a central controller to manage many lightweight APs?", ["Autonomous", "Ad hoc", "Controller-based (WLC)", "Mesh only"], 2, "A wireless LAN controller centrally configures lightweight APs, pushing channels, power settings and roaming policy.", ["Autonomous APs are each configured individually.", "Ad hoc has no APs.", "", "A mesh can be controller-based, but mesh describes how APs connect."]],
["2.4", "How tall is 1U?", ["1 in", "1.75 in", "2 in", "3.5 in"], 1, "One rack unit (1U) is 1.75 in (4.45 cm). A full rack is typically 42U.", ["1 in isn't a rack unit.", "", "2 in isn't a rack unit.", "3.5 in is 2U."]],
["2.4", "Equipment fronts should face which aisle?", ["Hot aisle", "Cold aisle", "Either", "Neither"], 1, "Intake from the cold aisle, exhaust to the hot aisle. Match port-side intake/exhaust fans to the layout.", ["The hot aisle is where exhaust goes.", "", "Direction matters for airflow.", "Fronts face the cold aisle."]],
["2.4", "Which UPS type gives the cleanest power by always running the load from the inverter?", ["Standby", "Line-interactive", "Online (double conversion)", "Generator"], 2, "An online (double-conversion) UPS always runs the load from its inverter, so there's no switchover gap and the power is clean.", ["A standby UPS switches to battery only when power fails.", "Line-interactive regulates voltage but still switches over.", "", "A generator isn't a UPS and needs one to bridge its start-up."]],
["2.4", "Which fire suppression is preferred in a data center?", ["Wet-pipe sprinklers", "Clean agent / inert gas", "Foam", "Dry chemical extinguishers only"], 1, "Clean agents put out fires without damaging electronics. Pre-action and dry-pipe systems reduce accidental water discharge.", ["Water damages electronics.", "", "Foam damages equipment.", "Extinguishers alone aren't a room suppression system."]],
["2.4", "A telecom closet on each floor that connects back to the main equipment room is an:", ["MDF", "IDF", "Demarc", "DMZ"], 1, "An IDF is a telecom closet serving a floor or area. It connects back to the MDF, the main equipment room, often over fiber.", ["The MDF is the main room.", "", "The demarc is the ISP handoff point.", "A DMZ (screened subnet) is a network zone."]],
["3.1", "What must a change request include before you modify a production router?", ["Nothing if the change is urgent", "Approval and a backout (rollback) plan", "Only a config backup", "Vendor approval"], 1, "Request → impact assessment → approval → maintenance window → backout plan → implement → verify → document.", ["Urgency doesn't skip change control; emergency changes are still documented.", "", "A backup alone isn't approval.", "Vendors don't approve your changes."]],
["3.1", "An SLA promises \"five nines\" (99.999%). About how much downtime per year is that?", ["8.76 hours", "52.6 minutes", "5.26 minutes", "30 seconds"], 2, "99.999% availability allows 0.001% downtime: about 5.26 minutes a year. 99.9% ≈ 8.76 h and 99.99% ≈ 52.6 min.", ["8.76 hours is 99.9%.", "52.6 minutes is 99.99%.", "", "30 seconds is beyond five nines."]],
["3.1", "A vendor stops releasing security patches for a switch model. What has the switch reached?", ["End of life (EOL)", "End of support (EOS)", "Baseline", "Decommissioning"], 1, "End of support (EOS) means no more patches or support. EOL only means the product is no longer sold.", ["EOL means it's no longer sold, though it may still be patched.", "", "A baseline is an approved configuration.", "Decommissioning is removing the device."]],
["3.1", "Which diagram shows subnets, VLANs and routing rather than racks and cable runs?", ["Physical diagram", "Logical diagram", "Rack diagram", "Floor plan"], 1, "Physical diagrams show where things are; logical diagrams show how the network works.", ["A physical diagram shows cables and devices.", "", "A rack diagram shows what is in each U.", "A floor plan shows rooms."]],
["3.1", "After a ransomware infection is detected, which incident-response phase comes next?", ["Eradication", "Containment", "Lessons learned", "Recovery"], 1, "Preparation → detection → containment → eradication → recovery → lessons learned.", ["You eradicate after containing.", "", "Lessons learned is last.", "Recovery comes after eradication."]],
["3.1", "Configuration drift is best detected by:", ["Comparing running configs with a golden baseline", "Rebooting devices", "Upgrading firmware", "Disabling logging"], 0, "Configuration management tools flag differences from the approved baseline.", ["", "Rebooting doesn't detect drift.", "Upgrading firmware doesn't compare configs.", "Disabling logging hides problems."]],
["3.1", "Which tool tracks which subnets and IP addresses are allocated?", ["IPAM", "SIEM", "IDS", "SOAR"], 0, "IP address management (IPAM) tracks subnets and address assignments, often integrated with DHCP and DNS.", ["", "A SIEM correlates logs.", "An IDS detects attacks.", "SOAR automates security responses."]],
["3.2", "Which syslog severity is most critical?", ["0, Emergency", "7, Debug", "3, Error", "1, Alert"], 0, "0 Emergency, 1 Alert, 2 Critical, 3 Error, 4 Warning, 5 Notice, 6 Informational, 7 Debug.", ["", "7 is the least severe.", "3 is less severe than 0.", "1 is the second most severe."]],
["3.2", "Which technology records who talked to whom, on which ports, and how much, without payload?", ["NetFlow / IPFIX", "Packet capture", "Syslog", "SNMP traps"], 0, "NetFlow/IPFIX records flow metadata (source, destination, ports, bytes, time) without the payload, which is ideal for traffic analysis.", ["", "A packet capture records full payloads.", "Syslog carries device logs.", "SNMP traps are device alerts."]],
["3.2", "An interface shows many giants. What is the most likely cause?", ["Bad cable", "Jumbo frames arriving on a port without jumbo support", "Duplex mismatch", "STP loop"], 1, "Giants are frames over 1518 bytes. Runts (under 64 bytes) usually come from collisions or a duplex mismatch.", ["A bad cable typically causes CRC errors.", "", "A duplex mismatch causes runts and late collisions.", "An STP loop causes broadcast storms."]],
["3.2", "Which capture method also catches malformed frames and physical-layer errors?", ["SPAN port", "Network tap", "NetFlow", "SNMP polling"], 1, "A hardware tap copies everything on the wire. A SPAN port may drop errored frames or oversubscribe.", ["A SPAN port may drop errored frames and can oversubscribe.", "", "NetFlow keeps only metadata.", "SNMP polling reads counters, not frames."]],
["3.2", "Which system collects logs from many devices, correlates them and alerts on security events?", ["SIEM", "IPAM", "NMS ping monitor", "CDN"], 0, "A SIEM aggregates logs from many sources, correlates events and raises alerts. Clocks must be synced with NTP for correlation to work.", ["", "IPAM tracks addresses.", "An NMS ping monitor checks availability only.", "A CDN delivers content."]],
["3.3", "The business can lose at most 4 hours of data. Which metric is this?", ["RTO", "RPO", "MTTR", "MTBF"], 1, "RPO is acceptable data loss, which drives backup frequency. RTO is acceptable downtime.", ["RTO is acceptable downtime.", "", "MTTR is average repair time.", "MTBF is average time between failures."]],
["3.3", "A recovery site has equipment and connectivity, but data must be restored before it can take over. Which type is it?", ["Hot", "Warm", "Cold", "Mobile"], 1, "A hot site has current replicated data. A cold site has space and power only.", ["A hot site already has current data.", "", "A cold site has no equipment.", "Mobile isn't the textbook term for this."]],
["3.3", "Which recovery site gives the fastest recovery?", ["Cloud site", "Hot site", "Warm site", "Cold site"], 1, "The textbook answer is the hot site. A cloud site counts only if it is kept hot. One quiz in your materials marks \"cloud\" as correct.", ["A cloud site is fastest only if it's kept hot. One quiz in your materials marks this wrong.", "", "A warm site needs its data restored first.", "A cold site is the slowest."], 1],
["3.3", "Which backup copies changes since the last full backup and grows until the next full?", ["Incremental", "Differential", "Snapshot", "Full"], 1, "A restore needs the full backup plus the latest differential. Incremental restores need the full plus every incremental.", ["Incremental copies changes since the last backup of any kind.", "", "A snapshot is a point-in-time image.", "Full copies everything every time."]],
["3.3", "Two firewalls both pass traffic and share the load. If one fails, the other carries everything. This is:", ["Active-passive", "Active-active", "Cold standby", "Tabletop"], 1, "In active-active, every node carries load and survivors absorb a failed node's share. In active-passive, the standby is idle until failover.", ["In active-passive, the standby carries no load.", "", "Cold standby is idle until needed.", "A tabletop is a discussion exercise."]],
["3.3", "A discussion-based walk-through of a disaster scenario with no systems touched is a:", ["Validation test", "Tabletop exercise", "Failover test", "Penetration test"], 1, "A tabletop exercise is a discussion-based walk-through of a scenario. Validation tests actually fail over or restore.", ["A validation test actually fails over or restores.", "", "A failover test touches real systems.", "A penetration test is a security attack simulation."]],
["3.4", "What are the DHCP messages, in order?", ["Discover, Offer, Request, Acknowledge", "Request, Offer, Discover, Ack", "Discover, Request, Offer, Ack", "Offer, Discover, Request, Ack"], 0, "DORA: the client broadcasts a Discover, the server Offers an address, the client Requests it, and the server Acknowledges. UDP 67 (server) and 68 (client).", ["", "The client must Discover first.", "The Offer comes before the Request.", "The client starts with Discover."]],
["3.4", "A printer must always get the same IP from DHCP. What do you configure?", ["Exclusion", "Reservation", "Shorter lease", "Option 3"], 1, "A reservation ties a MAC address to an IP. Exclusions keep addresses out of the pool.", ["An exclusion keeps addresses out of the pool.", "", "Lease length doesn't fix the address.", "Option 3 is the default gateway."]],
["3.4", "Hosts in VLAN 20 cannot reach the DHCP server in VLAN 10. What fixes it?", ["Port security", "DHCP relay (ip helper-address)", "STP PortFast", "A larger scope"], 1, "DHCP Discover is a broadcast, and routers don't forward broadcasts. A relay agent (ip helper-address) forwards it as unicast to the server.", ["Port security doesn't forward DHCP.", "", "PortFast speeds up link-up only.", "Scope size isn't the problem; reachability is."]],
["3.4", "Which DNS record maps a name to an IPv6 address?", ["A", "AAAA", "PTR", "CNAME"], 1, "AAAA (quad-A) records map a name to an IPv6 address. A records map to IPv4.", ["A maps a name to IPv4.", "", "PTR is a reverse lookup.", "CNAME is an alias."]],
["3.4", "Which DNS record holds SPF, DKIM and DMARC policies?", ["MX", "TXT", "SRV", "SOA"], 1, "TXT records hold free text, which is used for SPF, DKIM and DMARC email policies and for domain verification.", ["MX names mail servers.", "", "SRV locates services.", "SOA holds zone authority information."]],
["3.4", "What does DNSSEC provide?", ["Privacy (encryption)", "Integrity and authenticity of DNS answers", "Faster resolution", "Load balancing"], 1, "DNSSEC digitally signs DNS records so answers can be validated, which protects integrity and authenticity. For privacy, use DoH (443) or DoT (853).", ["DNSSEC doesn't encrypt; DoH and DoT do.", "", "DNSSEC adds validation work; it doesn't speed things up.", "DNSSEC doesn't distribute load."]],
["3.4", "An NTP server attached directly to a GPS reference clock is at which stratum?", ["0", "1", "2", "16"], 1, "A server attached directly to the reference clock is stratum 1. The reference clock itself is stratum 0.", ["Stratum 0 is the reference clock itself.", "", "Stratum 2 syncs from stratum 1.", "16 means unsynchronized."]],
["3.4", "When does a DHCP client first try to renew its lease?", ["At 25%", "At 50% of the lease", "At 87.5%", "When it expires"], 1, "A DHCP client first tries to renew with its original server at 50% of the lease time (T1).", ["25% isn't the renewal point.", "", "87.5% is the rebinding point.", "Waiting until expiry would cause an outage."]],
["3.5", "Admins reach console servers over a separate cellular link that still works when the production network fails. This is:", ["In-band management", "Out-of-band management", "Split tunnel", "Jump box"], 1, "Out-of-band management uses a separate path (console servers, cellular, a management network) that still works when production is down.", ["In-band uses the production network.", "", "Split tunnel is a VPN routing choice.", "A jump box is a host, not a separate path."]],
["3.5", "A remote-access VPN sends only corporate traffic through the tunnel; Internet traffic goes direct. This is a:", ["Full tunnel", "Split tunnel", "Site-to-site VPN", "Clientless VPN"], 1, "A split tunnel sends only corporate traffic through the VPN; Internet traffic goes direct. A full tunnel sends everything through the VPN.", ["A full tunnel sends all traffic through the VPN.", "", "Site-to-site links networks, not users.", "Clientless runs through a browser portal."]],
["3.5", "Users connect through a browser portal over TLS with no VPN client installed. This is a:", ["Site-to-site VPN", "Clientless VPN", "GRE tunnel", "IPsec transport mode"], 1, "A clientless VPN runs in the browser over TLS (an SSL/TLS VPN portal), with no client software installed.", ["Site-to-site links gateways.", "", "GRE is an unencrypted tunnel.", "IPsec transport mode needs a client."]],
["3.5", "A hardened host that admins log in to before reaching management interfaces is a:", ["Honeypot", "Jump box", "Proxy", "Load balancer"], 1, "A jump box is a hardened host that admins connect to first. It centralizes control and logging of privileged access.", ["A honeypot is a decoy.", "", "A proxy relays traffic.", "A load balancer distributes traffic."]],
["4.1", "Comparing hash values protects which part of the CIA triad?", ["Confidentiality", "Integrity", "Availability", "Non-repudiation"], 1, "A hash changes if even one bit of the data changes, so matching hashes prove integrity.", ["Confidentiality is protected by encryption.", "", "Availability is protected by redundancy.", "Non-repudiation comes from signatures, not hashes alone."]],
["4.1", "A password plus an authenticator-app code is:", ["Single-factor", "Multifactor (know + have)", "Biometric", "SSO"], 1, "A password is something you know and an authenticator code is something you have: two different factors make it multifactor.", ["Two different categories make it multifactor.", "", "No biometric is involved.", "SSO means one login for many systems."]],
["4.1", "Which AAA protocol encrypts the entire payload, separates AAA functions and uses TCP 49?", ["RADIUS", "TACACS+", "Kerberos", "LDAP"], 1, "RADIUS uses UDP 1812/1813 and encrypts only the password. TACACS+ suits device administration.", ["RADIUS uses UDP and encrypts only the password.", "", "Kerberos is ticket-based SSO.", "LDAP is a directory protocol."]],
["4.1", "Users suddenly fail Kerberos logons, and their clocks are 10 minutes off from the domain controller. Why?", ["Kerberos is Microsoft-only", "Kerberos is time-sensitive (about 5 minutes of allowed skew)", "The certificate expired", "RADIUS is down"], 1, "Kerberos tickets are time-stamped and only about 5 minutes of clock skew is allowed, so fix NTP. Kerberos is an open MIT standard; one handout wrongly calls it Microsoft-only.", ["Kerberos is an open MIT standard. One handout says it's Microsoft-only; that's wrong.", "", "No certificate is involved in plain Kerberos.", "RADIUS isn't used here."], 1],
["4.1", "Permissions are assigned to job roles, and users get roles. This is:", ["DAC", "RBAC", "MAC", "Rule-based"], 1, "Per-user assignment by the owner is closer to DAC. One quiz in your materials gets this wrong.", ["DAC means the owner decides access.", "", "MAC uses labels and clearances.", "Rule-based uses conditions, not roles."], 1],
["4.1", "Signing a message with your private key provides:", ["Confidentiality", "Integrity and non-repudiation", "Availability", "Compression"], 1, "To keep a message confidential, encrypt it with the recipient's public key.", ["Encrypting with the recipient's public key gives confidentiality.", "", "Signatures don't affect availability.", "Signing doesn't compress."]],
["4.1", "A decoy system set up to lure and study attackers is a:", ["Honeypot", "Bastion host", "Sandbox", "Proxy"], 0, "A honeypot is a decoy system that lures attackers so you can detect and study them. Several together form a honeynet.", ["", "A bastion host is a hardened jump box.", "A sandbox isolates code execution.", "A proxy relays traffic."]],
["4.1", "A small room between two interlocking doors that stops tailgating is an:", ["Access control vestibule", "Badge reader", "Bollard", "Faraday cage"], 0, "An access control vestibule (formerly a mantrap) has two interlocking doors that admit one person at a time, which stops tailgating.", ["", "A badge reader allows entry but doesn't stop tailgating by itself.", "Bollards stop vehicles.", "A Faraday cage blocks radio signals."]],
["4.1", "Which regulation protects payment cardholder data?", ["GDPR", "PCI DSS", "HIPAA", "SOX"], 1, "PCI DSS is the standard that protects payment cardholder data. GDPR covers EU personal data privacy.", ["GDPR covers EU personal data privacy.", "", "HIPAA covers US health data.", "SOX covers financial reporting."]],
["4.2", "An attacker sends forged ARP replies to become the gateway. What attack is this, and which defense stops it?", ["VLAN hopping / BPDU Guard", "ARP poisoning (on-path) / Dynamic ARP Inspection", "MAC flooding / STP", "DNS poisoning / DoH"], 1, "Forged ARP replies map the attacker's MAC to the gateway's IP, putting them on-path. Dynamic ARP Inspection drops ARP packets that don't match the DHCP snooping bindings.", ["VLAN hopping abuses trunking, not ARP.", "", "MAC flooding fills the CAM table.", "DNS poisoning forges DNS answers."]],
["4.2", "An attacker sends frames with two 802.1Q tags to reach another VLAN. What is this?", ["Switch spoofing", "Double tagging", "MAC flooding", "ARP spoofing"], 1, "Double tagging hides an inner 802.1Q tag behind an outer native-VLAN tag. The first switch strips the outer tag and the frame lands in the target VLAN. It works one way only.", ["Switch spoofing negotiates a trunk using DTP.", "", "MAC flooding fills the MAC table.", "ARP spoofing forges ARP replies."]],
["4.2", "Flooding a switch's MAC table so it forwards frames out every port like a hub is:", ["MAC flooding", "DHCP starvation", "Evil twin", "DDoS"], 0, "MAC flooding fills the switch's MAC (CAM) table, so it floods frames out every port like a hub and the attacker can sniff them. Port security limits MACs per port.", ["", "DHCP starvation drains the address pool.", "An evil twin is a rogue AP.", "DDoS attacks availability."]],
["4.2", "An employee holds the door open for a stranger carrying boxes. This is:", ["Tailgating", "Piggybacking", "Shoulder surfing", "Vishing"], 1, "Piggybacking is following someone in with their consent, like an employee holding the door. Tailgating is without consent.", ["Tailgating is without the employee's consent.", "", "Shoulder surfing is watching screens or keypads.", "Vishing is voice phishing."]],
["4.2", "Small spoofed queries to open DNS servers trigger large responses sent to the victim. This is:", ["Amplification/reflection DDoS", "SYN flood", "Brute force", "Replay"], 0, "Amplification/reflection DDoS sends small spoofed queries to open servers (DNS, NTP), which send much larger responses to the victim. It targets availability.", ["", "A SYN flood exhausts half-open connections.", "Brute force guesses passwords.", "A replay attack resends captured traffic."]],
["4.2", "A rogue AP copies the corporate SSID and kicks clients off the real AP to capture logins. This is:", ["War driving", "Evil twin with deauthentication", "Bluejacking", "Rogue DHCP"], 1, "An evil twin copies the real SSID, and a deauthentication attack pushes clients off the real AP onto it. Detect it with a wireless IDS/IPS.", ["War driving is scanning for networks.", "", "Bluejacking sends Bluetooth messages.", "A rogue DHCP server hands out addresses."]],
["4.3", "In 802.1X, what role does the switch play?", ["Supplicant", "Authenticator", "Authentication server", "CA"], 1, "In 802.1X the switch (or AP) is the authenticator: it relays credentials between the client (supplicant) and the RADIUS authentication server.", ["The supplicant is the client.", "", "The authentication server is RADIUS.", "A CA issues certificates."]],
["4.3", "Which switch feature blocks rogue DHCP servers on access ports?", ["DHCP snooping", "Port mirroring", "PortFast", "LACP"], 0, "DHCP snooping trusts only the ports facing real DHCP servers and drops server messages (Offer, Ack) arriving on untrusted access ports.", ["", "Port mirroring copies traffic.", "PortFast speeds up link-up.", "LACP bundles links."]],
["4.3", "Choose two. Which steps help prevent VLAN hopping?", ["Disable DTP / set access ports statically", "Use VLAN 1 as native", "Move the native VLAN to an unused ID", "Allow all VLANs on all trunks"], [0, 2], "Turning off DTP and setting access ports statically stops switch spoofing. Moving the native VLAN to an unused ID defeats double tagging. Also keep hosts off the native VLAN.", ["", "VLAN 1 as native is the default and the risk.", "", "Allowing all VLANs widens the attack surface."]],
["4.3", "An ACL has \"permit ip any any\" as line 1 and \"deny tcp host 10.1.1.5 any eq 23\" as line 2. What happens to Telnet from 10.1.1.5?", ["Denied", "Permitted, because line 1 matches first", "Logged only", "Depends on the implicit deny"], 1, "ACLs are processed top-down and the first match wins. Put specific rules before general ones.", ["The deny on line 2 is never reached, because line 1 already matched.", "", "Nothing is logged without the log keyword.", "The implicit deny is only reached if nothing matches."]],
["4.3", "Which EAP method is strongest because it uses certificates on both client and server?", ["PEAP", "EAP-TTLS", "EAP-TLS", "EAP-MD5"], 2, "EAP-TLS uses certificates on both the client and the server, so both sides prove their identity. PEAP and EAP-TTLS use only a server certificate.", ["PEAP uses a server certificate only.", "EAP-TTLS uses a server certificate only.", "", "EAP-MD5 is weak and has no certificates."]],
["4.3", "Which switch feature blocks rogue IPv6 router advertisements?", ["DAI", "RA Guard", "BPDU Guard", "Storm control"], 1, "RA Guard blocks IPv6 Router Advertisements on ports where no router should be, because rogue RAs can redirect IPv6 traffic.", ["DAI checks ARP.", "", "BPDU Guard stops rogue switches.", "Storm control limits floods."]],
["4.3", "Public web and mail servers belong in:", ["The internal LAN", "A screened subnet", "VLAN 1", "The guest network"], 1, "A compromised public server then cannot reach the internal LAN directly. It was formerly called a DMZ.", ["Public servers inside the LAN expose internal systems if compromised.", "", "VLAN 1 is the default VLAN.", "The guest network is for visitors."]],
["4.3", "Which switch feature limits a port to specific learned MAC addresses?", ["Port security", "BPDU Guard", "Root Guard", "Storm control"], 0, "Port security limits which and how many MAC addresses a port accepts. Sticky learning plus violation shutdown is a common setup.", ["", "BPDU Guard reacts to BPDUs.", "Root Guard protects the root election.", "Storm control limits floods."]],
["5.1", "What is the first step of the troubleshooting methodology?", ["Establish a theory", "Identify the problem", "Test the theory", "Document findings"], 1, "1 Identify, 2 Theory, 3 Test, 4 Plan, 5 Implement or escalate, 6 Verify, 7 Document.", ["You theorize after identifying.", "", "You test after theorizing.", "Documenting is last."]],
["5.1", "After implementing a fix, what comes next?", ["Document findings", "Verify full system functionality and implement preventive measures", "Establish a plan", "Escalate"], 1, "Step 6 is verifying full system functionality (and adding preventive measures). You document only after confirming the fix worked.", ["You verify before documenting.", "", "Planning comes before implementing.", "Escalation is part of step 5."]],
["5.1", "Your theory tested false. What next?", ["Escalate immediately", "Establish a new theory or escalate", "Document findings", "Implement anyway"], 1, "An untested or disproven theory goes back to step 2: form a new theory, or escalate if it's beyond your scope.", ["Escalation is an option, but a new theory comes first.", "", "Nothing is solved yet.", "Never implement an untested fix."]],
["5.1", "Which action belongs to \"Identify the problem\"?", ["Determine if anything has changed", "Replace the switch", "Schedule a maintenance window", "Update the ticket with the root cause"], 0, "Determining what changed is part of step 1, identifying the problem, along with questioning users and duplicating the issue.", ["", "Replacing the switch is implementing (step 5).", "Scheduling is the plan of action (step 4).", "Updating the ticket is documenting (step 7)."]],
["5.1", "What is the correct order of the four-step ping test?", ["Gateway → remote → loopback → own IP", "127.0.0.1 → own IP → default gateway → remote host", "Remote → gateway → own IP → loopback", "Own IP → loopback → remote → gateway"], 1, "This tests the TCP/IP stack, the NIC, the local network and then routing, in that order. Ping by name last to test DNS.", ["Starting at the gateway skips checking your own TCP/IP stack and NIC first.", "", "This is the order reversed.", "The loopback comes before your own IP."]],
["5.2", "Which tool finds the distance to a break in a copper cable?", ["Toner probe", "TDR", "OTDR", "Loopback plug"], 1, "A time-domain reflectometer (TDR) sends a pulse down copper and times the reflection to find the distance to a break. An OTDR does the same for fiber.", ["A toner traces cables; it doesn't measure distance.", "", "An OTDR is for fiber.", "A loopback plug tests ports."]],
["5.2", "Which tool identifies which patch panel port a wall jack connects to?", ["Toner and probe", "Multimeter", "Spectrum analyzer", "Crimper"], 0, "A toner and probe (fox and hound) puts a tone on the wall jack, and you trace it at the patch panel.", ["", "A multimeter measures voltage and resistance.", "A spectrum analyzer is for RF.", "A crimper attaches connectors."]],
["5.2", "A new fiber link has no light at either end, and the SFPs match. What is a common simple cause?", ["TX/RX strands reversed", "Wrong VLAN", "DNS failure", "Duplex mismatch"], 0, "Transmit must connect to receive. If the strands are swapped, neither end sees light. Also check for dirty connectors, wavelength mismatch and bend radius.", ["", "A VLAN is Layer 2 and can't stop light.", "DNS is Layer 7.", "Fiber links don't have the duplex problems copper does."]],
["5.2", "A switch port shows \"err-disabled\" after someone plugged a small switch into it. What likely caused it?", ["Administrative shutdown", "BPDU Guard or a port-security violation", "Duplex mismatch", "DNS failure"], 1, "BPDU Guard (a BPDU from the small switch) or a port-security violation err-disables the port. Fix the cause, then shut / no shut to recover.", ["Administrative shutdown shows as \"administratively down\".", "", "A duplex mismatch causes errors, not err-disabled.", "DNS has nothing to do with port state."]],
["5.2", "A new PoE+ camera reboots constantly on a switch that supports only 802.3af. What is the issue?", ["Wrong VLAN", "Incorrect PoE standard (insufficient power)", "Bad DNS", "Port security"], 1, "A PoE+ (802.3at) device needs up to about 25.5 W, but 802.3af gives only about 12.95 W, so the camera browns out and reboots. Also check the switch's total budget with show power inline.", ["The VLAN doesn't affect power.", "", "DNS doesn't affect power.", "A port-security violation would err-disable the port, not cause reboots."]],
["5.2", "Which tool shines a red laser down a fiber to show breaks and tight bends?", ["OTDR", "Visual fault locator", "Light meter", "Toner"], 1, "An OTDR gives the distance to the fault; a light meter measures signal level.", ["An OTDR measures the distance to a fault using reflections.", "", "A light meter measures power level.", "A toner is for copper."]],
["5.3", "Users can ping 8.8.8.8 but cannot open websites by name. What is the most likely cause?", ["Bad cable", "DNS problem", "Wrong default gateway", "DHCP failure"], 1, "Reaching 8.8.8.8 proves Layers 1–3 and the gateway work, so a failure by name points to DNS. Confirm with nslookup.", ["A bad cable would stop the ping to 8.8.8.8 too.", "", "The ping to 8.8.8.8 proves the gateway works.", "DHCP clearly worked."]],
["5.3", "A PC reaches hosts on its own subnet but nothing remote. What is the most likely cause?", ["Wrong default gateway", "Bad DNS", "Duplex mismatch", "APIPA"], 0, "Traffic to other subnets goes to the default gateway, so a wrong or missing gateway breaks only remote access.", ["", "Bad DNS breaks names, not local-vs-remote reachability.", "A duplex mismatch causes slowness everywhere.", "APIPA would break local access too."]],
["5.3", "Someone connects a second cable between two switches, and the network grinds to a halt with broadcast storms. What happened?", ["Switching loop (STP problem)", "DHCP exhaustion", "ARP poisoning", "Routing loop"], 0, "A second cable between switches creates a Layer 2 loop. Without STP (or with PortFast and no BPDU Guard), broadcasts circulate forever.", ["", "DHCP exhaustion causes APIPA addresses, not storms.", "ARP poisoning is quiet interception.", "A routing loop is Layer 3 and shows TTL expiring."]],
["5.3", "New laptops get APIPA addresses; existing devices work. The /24 scope has 250 active leases. What is the cause?", ["Scope exhaustion", "DNS failure", "STP blocking", "Wrong gateway"], 0, "A /24 scope has 254 usable addresses and 250 are leased, so new clients get no offer and fall back to APIPA. Shorten leases or enlarge the scope.", ["", "DNS doesn't hand out addresses.", "STP doesn't affect DHCP once the link is up.", "A wrong gateway doesn't stop leases."]],
["5.3", "After a desk move, a user gets an address from a different subnet than their team. What is the most likely cause?", ["Wrong VLAN on the switch port", "Bad DNS server", "Expired certificate", "Duplex mismatch"], 0, "The access port is in the wrong VLAN, so the user gets DHCP from that VLAN's subnet. Check with show vlan brief.", ["", "DNS doesn't assign subnets.", "Certificates have nothing to do with addressing.", "A duplex mismatch causes errors, not a wrong subnet."]],
["5.3", "Clients get an unexpected gateway and DNS server, and traffic is being intercepted. What is the most likely cause?", ["Rogue DHCP server", "Scope exhaustion", "Wrong subnet mask", "Bad cable"], 0, "A rogue DHCP server hands out its own gateway and DNS, which puts the attacker on-path. Mitigate with DHCP snooping.", ["", "Exhaustion gives no lease at all.", "A wrong subnet mask doesn't hand out wrong DNS servers.", "A bad cable gives no connectivity."]],
["5.4", "VoIP calls are choppy because packets arrive at uneven intervals. Which metric is this?", ["Latency", "Jitter", "Throughput", "Bandwidth"], 1, "Jitter is the variation in delay between packets, which makes VoIP choppy. Fix it with QoS and jitter buffers.", ["Latency is delay; jitter is the variation in delay.", "", "Throughput is achieved data rate.", "Bandwidth is capacity."]],
["5.4", "Two neighboring APs both on channel 6 cause:", ["Co-channel interference", "Crosstalk", "Jumbo frames", "Asymmetric routing"], 0, "APs on the same channel must take turns using the air (co-channel interference). Plan channels 1, 6 and 11 in 2.4 GHz.", ["", "Crosstalk is a copper wiring problem.", "Jumbo frames are an MTU setting.", "Asymmetric routing is a path issue."]],
["5.4", "Users behind an elevator shaft and concrete walls have weak Wi-Fi. Which effect is mainly to blame?", ["Absorption and reflection (attenuation)", "Wrong SSID", "DHCP exhaustion", "Expired certificate"], 0, "Concrete absorbs and metal reflects RF, which weakens the signal. Fix it with AP placement or more APs, guided by a site survey.", ["", "A wrong SSID gives no association at all.", "DHCP exhaustion gives no address, not a weak signal.", "Certificates don't affect signal strength."]],
["5.4", "A 10 Gbps server farm connects to the core through a single 1 Gbps uplink. What is this?", ["Bottleneck", "Jitter", "Crosstalk", "Duplex mismatch"], 0, "Throughput is capped by the slowest link in the path, so the single 1 Gbps uplink is the bottleneck.", ["", "Jitter is delay variation.", "Crosstalk is cabling.", "A duplex mismatch causes errors."]],
["5.5", "Which command shows the path to a host and where traffic stops?", ["ipconfig", "tracert / traceroute", "arp -a", "nslookup"], 1, "tracert/traceroute lists each router hop by sending packets with increasing TTL, so you see where traffic stops.", ["ipconfig shows local settings.", "", "arp -a shows the ARP cache.", "nslookup queries DNS."]],
["5.5", "Which Windows command lists listening ports and active connections?", ["netstat -an", "nslookup", "pathping", "hostname"], 0, "netstat -an lists all connections and listening ports in numeric form. Add -b (as admin) to see the owning program.", ["", "nslookup queries DNS.", "pathping is a path plus loss test.", "hostname prints the computer name."]],
["5.5", "Which Cisco command shows which MAC addresses were learned on which ports?", ["show mac address-table", "show ip route", "show vlan brief", "show running-config"], 0, "show mac address-table lists the MAC addresses each switch port has learned, so you can trace a device to its port.", ["", "show ip route shows routes.", "show vlan brief shows VLAN membership.", "show running-config shows the configuration."]],
["5.5", "Which tool discovers live hosts, open ports and service versions?", ["nmap", "iperf", "dig", "tcpdump"], 0, "nmap scans for live hosts, open ports, service versions and OS fingerprints. Run it only with written permission on networks you don't own.", ["", "iperf measures throughput.", "dig queries DNS.", "tcpdump captures packets."]],
["5.5", "You are at an unlabeled wall jack. Which protocol tells you which switch and port it connects to?", ["LLDP / CDP", "SNMP", "NTP", "ARP"], 0, "LLDP (the open standard) and CDP (Cisco-only) neighbor discovery report the switch name and port you're connected to.", ["", "SNMP manages devices.", "NTP syncs time.", "ARP maps IP to MAC."]],
["5.5", "Which Linux command replaces ifconfig?", ["ip", "ss", "dig", "route"], 0, "The ip command (ip addr, ip route, ip link) replaces the older ifconfig and route tools on Linux.", ["", "ss shows sockets (it replaces netstat).", "dig queries DNS.", "route is the old routing command that ip also replaces."]],
["4.1", "You are installing 30 new IP cameras. What should you do FIRST to reduce the risk they bring?", ["Change their default credentials and put them on an isolated VLAN", "Give them public IP addresses for easy remote viewing", "Enable UPnP so they can open the ports they need", "Put them on the staff VLAN so the help desk can reach them"], 0, "IoT devices often ship with default passwords and are rarely patched. Changing the credentials and isolating them on their own VLAN, with ACLs allowing only the traffic they need, limits what an attacker can do with a compromised camera.", ["", "Public addresses expose the cameras directly to Internet scanning.", "UPnP lets devices open firewall ports by themselves, which widens the attack surface.", "Mixing cameras with staff PCs means one compromised camera can reach every PC."]],
["4.1", "For an ICS/SCADA system that runs a water treatment plant, which part of the CIA triad usually comes first?", ["Confidentiality", "Integrity", "Availability", "Non-repudiation"], 2, "Operational technology controls physical processes, so a stopped plant is the worst outcome. That is why these systems are often left unpatched and must be protected by strong segmentation instead.", ["Confidentiality matters, but a leak is less harmful than the plant stopping.", "Integrity matters, but OT design starts from keeping the process running.", "", "Non-repudiation is not part of the CIA triad."]],
["4.1", "The most critical controllers in a power plant have no connection to the business network or the Internet at all. What is this called?", ["Screened subnet", "Air gap", "Port security", "Split tunnel"], 1, "An air gap physically separates a system from every other network, the strongest form of isolation for critical OT systems.", ["A screened subnet holds public-facing servers between two firewalls; it is still connected.", "", "Port security limits MAC addresses on a switch port.", "A split tunnel is a VPN setting."]],
["1.4", "Which protocol sets up, manages and ends VoIP calls?", ["SIP (5060/5061)", "RTP (dynamic UDP ports)", "SMTP (25)", "SNMP (161)"], 0, "SIP is the signaling protocol for VoIP: it rings the phone, negotiates the call and hangs it up. Port 5060 is cleartext, 5061 is SIP over TLS.", ["", "RTP carries the voice itself once the call is set up.", "SMTP sends email.", "SNMP monitors and manages devices."]],
["1.4", "During a VoIP call, which protocol carries the actual voice packets?", ["SIP", "RTP", "LDAP", "NTP"], 1, "After SIP sets the call up, RTP (Real-time Transport Protocol) carries the audio over dynamic UDP ports.", ["SIP handles call setup and teardown, not the media.", "", "LDAP queries directories.", "NTP synchronizes clocks."]],
["1.2", "Voice packets are marked so routers send them ahead of other traffic. Which Layer 3 field carries that marking?", ["DSCP", "TTL", "802.1Q VLAN ID", "MAC OUI"], 0, "QoS marks packets with a DSCP value in the IP header (802.1p CoS is the Layer 2 equivalent). Routers and switches then queue marked voice packets first.", ["", "TTL limits how many hops a packet can take.", "The VLAN ID separates traffic into VLANs; the tag's separate priority bits (802.1p) are the Layer 2 marking.", "The OUI is the vendor part of a MAC address."]],
["5.4", "On VoIP calls, people keep talking over each other because of long pauses before the other side hears them. Which metric is the problem?", ["Jitter", "Latency", "Packet loss", "Throughput"], 1, "Latency is delay. When the one-way delay is high, each speaker hears the other late, so they interrupt each other. Jitter causes choppy audio instead.", ["Jitter (variation in delay) makes audio choppy or robotic.", "", "Packet loss causes gaps and dropouts.", "Throughput is the data rate actually achieved; voice needs very little."]],
["1.5", "A remote office connects over a geostationary satellite link. What problem should users expect?", ["High latency", "No encryption is possible", "Speed is capped at 10 Mbps by the standard", "It cannot carry VPN traffic"], 0, "Signals travel to a satellite about 36,000 km up and back, so geostationary links add roughly 600 ms or more of round-trip delay. Low-earth-orbit services are much faster.", ["", "A VPN or TLS encrypts traffic over any link.", "There is no such cap; satellite plans vary widely.", "VPNs work over satellite, just with extra delay."]],
["1.8", "A company combines MPLS, broadband and LTE links and steers each application over the best one from a central policy. What is this?", ["SD-WAN", "VXLAN", "NFV", "Metro Ethernet"], 0, "SD-WAN manages several WAN links as one, choosing a path per application by central policy, and supports zero-touch provisioning of new branches.", ["", "VXLAN stretches Layer 2 segments across a Layer 3 network.", "NFV runs network appliances as virtual machines.", "Metro Ethernet is a single type of WAN circuit."]],
["3.5", "Which method is the secure standard for managing a router's command line remotely?", ["SSH", "Telnet", "RDP", "HTTP"], 0, "SSH (TCP 22) encrypts the whole management session, including the login.", ["", "Telnet sends everything, including passwords, in clear text.", "RDP is a graphical remote desktop for Windows, not router CLIs.", "HTTP is unencrypted; use HTTPS for a web interface."]],
["1.8", "Which is a valid shortened form of 2001:0db8:0000:0000:0000:8a2e:0370:7334?", ["2001:db8::8a2e:370:7334", "2001:db8:::8a2e:370:7334", "2001:db8::8a2e::370:7334", "2001:db8:0:8a2e:370:7334"], 0, "Drop leading zeros in each group, then replace the one run of all-zero groups with ::. Expanding it back gives exactly eight groups.", ["", "::: is not valid notation.", ":: can appear only once, otherwise nobody can tell how many zeros each one stands for.", "This drops two zero groups, leaving only six groups."]],
["1.8", "A host builds its own IPv6 address from the prefix in a Router Advertisement, with no server involved. What is this?", ["SLAAC", "Stateful DHCPv6", "APIPA", "NAT64"], 0, "Stateless address autoconfiguration (SLAAC) combines the /64 prefix from the RA with an interface ID the host creates itself.", ["", "Stateful DHCPv6 needs a DHCPv6 server to assign the address.", "APIPA is the IPv4 169.254.x.x fallback.", "NAT64 translates between IPv6 and IPv4."]],
["3.2", "What describes the values an SNMP agent can report, each identified by an OID?", ["The MIB", "The community string", "A syslog facility", "A NetFlow record"], 0, "The management information base (MIB) defines every object a device exposes, and each object has a numeric OID such as 1.3.6.1.2.1.1.5 for the device name.", ["", "The community string is SNMPv1/v2c's shared password.", "A syslog facility labels which part of a system produced a log message.", "NetFlow records summarize traffic conversations."]],
["3.2", "Before you can tell whether 70% link utilization at 10 a.m. is a problem, what do you need?", ["A baseline of normal performance", "A full packet capture", "A higher syslog severity", "A new SLA"], 0, "A baseline records what normal looks like for that time and link. Without it you can't tell an anomaly from a busy Monday morning.", ["", "A capture shows packet contents, not whether the level is unusual.", "Severity levels classify log messages, not utilization.", "An SLA sets promises to customers; it doesn't describe your normal traffic."]],
["3.2", "An interface shows a rising count of runts. What are runts?", ["Frames smaller than 64 bytes", "Frames larger than 1518 bytes", "Frames dropped because buffers were full", "Frames carrying an 802.1Q tag"], 0, "Runts are undersized frames, usually left over from collisions, often caused by a duplex mismatch.", ["", "Oversized frames are giants.", "Those are discards (drops).", "Tagged frames are normal on trunks."]],
["3.2", "Which syslog severity level is used for routine Informational messages?", ["2", "4", "6", "7"], 2, "Severity runs from 0 (Emergency) to 7 (Debug). Level 6 is Informational and level 5 is Notice.", ["2 is Critical.", "4 is Warning.", "", "7 is Debug, the most detailed."]]
];
